M_sun = 1.98847e30        # kg

def schwarzschild_radius(M):
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    return 1.5 * schwarzschild_radius(M)

def critical_impact_parameter(M):
    # b_crit = 3*sqrt(3)*GM/c^2  (impact parameter that separates capture from escape)
    return 3 * math.sqrt(3) * G * M / c**2

def angular_separation(b, d):
    # Approximate for small angles (rad)
    return b / d

def horizon_area(r, M):
    # A = 4π r_s^2
    return 4 * math.pi * (schwarzschild_radius(M))**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def entropy_monotonic(series):
    prev = series[0]
    for val in series[1:]:
        if not (val >= prev):
            return False
        prev = val
    return True

def load_gwtc_catalog(path):
    try:
        with open(path, 'r') as f:
            data = json.load(f)
        events = data.get('events', [])
        masses = []
        for ev in events:
            m1 = ev.get('mass_1_source')
            m2 = ev.get('mass_2_source')
            if m1 is not None and m2 is not None:
                masses.append(m1 + m2)
        return masses
    except Exception as e:
        print(f"Failed to load GWTC catalog: {e}")
        return []

def main():
    # Example usage with solar‑mass scales
    M = M_sun
    r_s = schwarzschild_radius(M)
    r_ph = photon_sphere_radius(M)
    b_crit = critical_impact_parameter(M)
    d = 1e3 * r_s  # distance comparable to Schwarzschild radius
    theta_crit = angular_separation(b_crit, d)
    print(f"Schwarzschild radius (M={M/M_sun:.2f} M_sun): {r_s:.3e} m")
    print(f"Photon‑sphere radius: {r_ph:.3e} m")
    print(f"Critical impact parameter: {b_crit:.3e} m")
    print(f"Critical angular separation: {theta_crit:.3e} rad ({theta_crit*206265:.3f} arcsec)")

    # Entropy monotonicity test (placeholder series)
    entropy_series = [1.2, 1.5, 1.8, 2.1]
    print("Entropy monotonicity:", "PASS" if entropy_monotonic(entropy_series) else "FAIL")

    # Load GWTC catalog if environment variable provided
    catalog_path = os.getenv('GWTC_CATALOG_PATH')
    if catalog_path and os.path.isfile(catalog_path):
        masses = load_gwtc_catalog(catalog_path)
        if masses:
            avg_mass = sum(masses) / len(masses)
            print(f"Average binary mass from GWTC catalog: {avg_mass/M_sun:.2f} M_sun")
        else:
