# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
M_sun = 1.98847e30      # kg

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    """Photon sphere radius for a non-rotating BH: 1.5 * r_s"""
    return 1.5 * schwarzschild_radius(M)

def critical_impact_parameter(M):
    """Critical angular diameter θ_c = 6√3 GM/(c^2 D) (radians)"""
    return 6 * math.sqrt(3) * G * M / (c**2)

def angular_diameter(M, D):
    """Apparent angular diameter of the BH θ = r_s/D (radians)"""
    return schwarzschild_radius(M) / D

def test_case(M_solar=M_sun, D_meters=1e3 * 3.085677581e16):
    """Compute and print the ratio of the critical impact parameter to the apparent size.
    If the ratio ≥ 1 the hypothesis is supported, otherwise it is falsified.
    """
    M = M_solar
    D = D_meters
    theta_c = critical_impact_parameter(M)
    theta = angular_diameter(M, D)
    ratio = theta_c / theta
    print(f"Critical impact parameter (θ_c): {theta_c:.3e} rad")
    print(f"Apparent angular diameter (θ): {theta:.3e} rad")
    print(f"Ratio θ_c/θ = {ratio:.3e}")
    if ratio >= 1:
        print("PASS: Hypothesis supported")
    else:
        print("FAIL: Hypothesis falsified")

if __name__ == "__main__":
    test_case()

